import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Calculate plane dimensions from atlas region aspect ratio (512 x 320)
  const atlasAspectRatio = 512 / 320;
  const planeHeight = 1.0;
  const planeWidth = planeHeight * atlasAspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load sprite texture
  const textureAsset = ctx.textureLoader('/prism-mock/home/nodes/floating-accent.png');

  // Create material with TSL texture node
  const colorNode = texture(textureAsset);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode,
    transparent: true
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config or defaults
  const position = config.position ?? [0, -0.35, -0.6];
  const rotation = config.rotation ?? [0, 0, 0];
  const scale = config.scale ?? [1, 1, 1];

  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // Setup cleanup handler
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
